using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ─── CalculateTotal: DataRow-driven tests ───────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0,  50.00,  DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10,  0.00,  DisplayName = "Zero price yields zero total")]
    [DataRow(10.00, 0, 0.10,  0.00,  DisplayName = "Zero quantity yields zero total")]
    [DataRow(99.99, 1, 1.0, 199.98,  DisplayName = "Max tax rate (100%)")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ─── CalculateTotal: invalid-input tests via DataRow ────────────────

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice",  DisplayName = "Negative price throws")]
    [DataRow(10.00, -1, 0.10, "quantity",   DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, "taxRate",    DisplayName = "Negative tax rate throws")]
    [DataRow(10.00, 1, 1.01,  "taxRate",    DisplayName = "Tax rate > 1 throws")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // ─── ApplyDiscount: DynamicData-driven tests ────────────────────────

    public static IEnumerable<object[]> DiscountTestCases
    {
        get
        {
            yield return new object[] { 100.00m, 0m,    100.00m, "No discount" };
            yield return new object[] { 100.00m, 10m,    90.00m, "10% discount" };
            yield return new object[] { 100.00m, 50m,    50.00m, "50% discount" };
            yield return new object[] { 100.00m, 100m,    0.00m, "Full discount" };
            yield return new object[] { 249.99m, 15m,  212.4915m, "Fractional result" };
            yield return new object[] {   0.00m, 25m,    0.00m, "Zero price, any discount" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(DiscountTestCases))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
    }

    // ─── ApplyDiscount: boundary / invalid via DynamicData method source ─

    public static IEnumerable<object[]> InvalidDiscountTestCases()
    {
        yield return new object[] { 100.00m, -1m,  "Below 0%" };
        yield return new object[] { 100.00m, 101m, "Above 100%" };
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountTestCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRange(
        decimal price, decimal discountPercent, string scenario)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName, $"Failed for scenario: {scenario}");
    }
}

